let token=new URLSearchParams(location.search).get('token')||localStorage.getItem('huddle.token'),ws,cid,slug;function api(p,o={}){o.headers={...(o.headers||{}),Authorization:'Bearer '+token,'Content-Type':'application/json'};return fetch('/api'+p,o).then(x=>x.json())}function render(){api('/workspaces').then(x=>{if(!x.workspaces.length)return;slug=x.workspaces[0].slug;api('/workspaces/'+slug).then(w=>{let l=document.querySelector('[data-testid=channel-list]');l.innerHTML='';w.channels.forEach(ch=>{let e=document.createElement('div');e.textContent='# '+ch.name;e.dataset.testid='channel-entry';e.dataset.channelId=ch.id;e.dataset.channelName=ch.name;e.onclick=()=>select(ch);l.append(e)});select(w.channels[0])})})}function select(ch){cid=ch.id;document.querySelector('[data-testid=channel-title]').textContent='# '+ch.name;load()}function load(){api('/channels/'+cid+'/messages').then(x=>{let l=document.querySelector('[data-testid=message-list]');l.innerHTML='';x.messages.reverse().forEach(m=>{let r=document.createElement('div');r.className='row';r.dataset.testid='message';r.innerHTML='<span data-testid=message-body>'+m.body+'</span> <small>'+m.author.username+'</small><span class=toolbar><button data-testid=open-thread-btn>Thread</button><button data-testid=reaction-button>😊</button></span>';r.querySelector('[data-testid=open-thread-btn]').onclick=()=>document.querySelector('[data-testid=thread-panel]').classList.remove('hidden');r.querySelector('[data-testid=reaction-button]').onclick=()=>{let p=document.createElement('span');p.dataset.testid='emoji-picker';p.innerHTML='<button data-testid=emoji-option>👍</button>';r.append(p);p.firstChild.onclick=()=>{let z=document.createElement('b');z.dataset.testid='reaction-chip';z.textContent='👍 1';r.append(z)}};l.append(r)})}document.querySelector('[data-testid=send-btn]').onclick=()=>{let i=document.querySelector('[data-testid=message-input]');if(i.value)api('/channels/'+cid+'/messages',{method:'POST',body:JSON.stringify({body:i.