cat > /app/start.sh <<'SH'
#!/bin/sh
set -e
rm -f /app/state.db
for n in 0 1 2; do NODE_ID=$n python3 /app/app.py >/tmp/huddle-$n.log 2>&1 & echo $! >> /tmp/huddle.pids; done
python3 - <<'PY'
import socketserver,socket,threading,sqlite3,json,re,time,os
DB='/app/state.db'
class S(socketserver.BaseRequestHandler):
 def setup(self):self.nick=None;self.token=None;self.joined=[];self.alive=True
 def send(self,x):self.request.sendall((x+'\r\n').encode())
 def handle(self):
  f=self.request.makefile('r')
  for line in f:
   a=line.strip().split(' ',2);cmd=a[0].upper(); rest=a[1:]
   if cmd=='PASS':self.token=rest[0] if rest else ''
   elif cmd=='NICK':
    n=rest[0] if rest else ''; 
    if any(x.nick==n for x in self.server.clients if x is not self):self.send(':irc 433 * '+n+' :Nickname in use');continue
    self.nick=n
   elif cmd=='USER' and self.token:
    c=sqlite3.connect(DB);r=c.execute('select user_id from tokens where token=?',(self.token,)).fetchone()
    if not r:self.send(':irc 464 * :Password incorrect');return
    self.uid=r[0];self.send(':irc 001 '+self.nick+' :Welcome');[self.send(':irc '+x+' '+self.nick+' :huddle') for x in ('002','003','004','005')];self.send(':irc 422 '+self.nick+' :MOTD')
   elif cmd=='PING':self.send(':irc PONG '+(' '.join(rest)))
   elif cmd=='JOIN':
    ch=rest[-1].lstrip(':');c=sqlite3.connect(DB);r=c.execute('select w.slug,c.name,c.id from channels c join workspaces w on w.id=c.ws where w.slug||"/"||c.name=?',(ch.lstrip('#'),)).fetchone()
    if not r:self.send(':irc 403 '+self.nick+' '+ch+' :No such channel');continue
    self.joined.append((r[2],ch));self.send(':'+self.nick+'!user@host JOIN :#'+ch);self.send(':irc 353 '+self.nick+' = #'+ch+' :'+self.nick);self.send(':irc 366 '+self.nick+' #'+ch+' :End of NAMES')
   elif cmd=='PRIVMSG':
    ch=rest[0].lstrip('#');b=rest[1].lstrip(':') if len(rest)>1 else '';c=sqlite3.connect(DB);r=c.execute('select c.id from channels c join workspaces w on w.id=c.ws where w.slug||"/"||c.name=?',(ch,)).fetchone()
    if r:
     c.execute('insert into messages(channel,author,body,created) values(?,?,?,datetime("now"))',(r[0],self.uid,b));c.commit()
   elif cmd=='QUIT':return
   else:
    if cmd not in ('NICK','USER','PASS'):self.send(':irc 421 '+self.nick+' '+cmd+' :Unknown command')
 def finish(self):
  try:self.request.close()
  except:pass
class T(socketserver.ThreadingMixIn,socketserver.TCPServer):allow_reuse_address=True
srv=T(('0.0.0.0',6667),S);srv.clients=[];srv.serve_forever()
